export interface ResourceCard {
	title: string
	line: string
	href: string
	/** The small gray line at the foot ("4 templates", "docs.acme.com"). */
	meta?: string
	cover?: ResourceCover
}
export type ResourceCover = { kind: 'creatives'; items: ResourceCreative[] } | { kind: 'code'; source: string; language?: string }
export interface ResourceCreative extends ImageSlot {
	brand?: string
	caption?: string
	tone?: 1 | 2 | 3 | 4
}
export interface ImageSlot {
	/** The image. */
	src?: string
	/** What it shows; empty when it is decoration. */
	alt?: string
	/** How it fills its box (object-fit); cover by default. */
	fit?: ImageFit
	/** Where it is anchored in its box (object-position), for example "50% 20%" or "top". */
	position?: string
}
export type ImageFit = 'cover' | 'contain' | 'fill' | 'none' | 'scale-down'
export interface ResourceRow {
	title: string
	line: string
	/** Leave it out for a row that is not live (it is not a link). */
	href?: string
	/** The badge on the right ("Coming soon"). */
	badge?: string
}
/**
 * <spyglass-resource-cards>

 */
export declare class ResourceCards extends HTMLElement {
  cards: ResourceCard[];
  rows: ResourceRow[];
  rowsLabel: string;
  columns: 2 | 3;
}
declare global {
  interface HTMLElementTagNameMap {
    'spyglass-resource-cards': ResourceCards;
  }
}

/**
 * <spyglass-code>

 */
export declare class Code extends HTMLElement {
  source: string;
  language: string;
}
declare global {
  interface HTMLElementTagNameMap {
    'spyglass-code': Code;
  }
}

export type ImageFit = 'cover' | 'contain' | 'fill' | 'none' | 'scale-down'
export type CreativeRatio = '4/5' | '1/1' | '3/4' | '7/5' | '3/5' | '9/16' | '16/9' | 'fill'
export type CreativeTone = 1 | 2 | 3 | 4
/**
 * <spyglass-creative-card>

 */
export declare class CreativeCard extends HTMLElement {
  src?: string | undefined;
  alt: string;
  fit?: ImageFit | undefined;
  position?: string | undefined;
  ratio: CreativeRatio;
  brand?: string | undefined;
  caption?: string | undefined;
  tone: CreativeTone;
  href?: string | undefined;
}
declare global {
  interface HTMLElementTagNameMap {
    'spyglass-creative-card': CreativeCard;
  }
}

export type BadgeVariant = 'default' | 'secondary' | 'outline' | 'destructive'
export type BadgeDot = 'magenta' | 'red' | 'orange' | 'yellow' | 'green' | 'cyan' | 'blue'
/**
 * <spyglass-badge>
 * @slot (default) The word.
 */
export declare class Badge extends HTMLElement {
  variant: BadgeVariant;
  dot?: BadgeDot | undefined;
}
declare global {
  interface HTMLElementTagNameMap {
    'spyglass-badge': Badge;
  }
}
